'use strict';
async function start(){
 const loadFeed = async () => {const response = await fetch('feed.json', {cache:'no-store'}); if(!response.ok) throw new Error('Feed unavailable'); const data=await response.json();if(!Array.isArray(data.contexts)||!Array.isArray(data.videos))throw new Error('Invalid feed');return data;};
 window.SEED=await loadFeed(); let feedVersion=JSON.stringify(window.SEED),feedRequest=0;
const $ = id => document.getElementById(id), KEY = 'yourtube.state.v1';
const blank = () => ({contextEdits:{},customContexts:[],deletedContexts:[],customVideos:[],hiddenVideos:[],saved:[]});
let state;
try { state = {...blank(),...JSON.parse(localStorage.getItem(KEY) || '{}')}; } catch { state = blank(); }
let active = window.SEED.focusContext || 'all', view = 'all', liveState = {mode:'connecting', message:'Connecting to local live service.'};
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function contexts(){ return [...window.SEED.contexts.map(c=>({...c,...state.contextEdits[c.id]})),...state.customContexts].filter(c=>!state.deletedContexts.includes(c.id)); }
function videos(){ const valid = new Set(contexts().map(c=>c.id)); return [...window.SEED.videos,...state.customVideos].filter(v=>valid.has(v.context)&&!state.hiddenVideos.includes(v.id)); }
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('Could not save to this browser.');return false}}
let toastTimer;function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2800)}
function selectContext(id){active=id;view='all';render()}
function render(){
 const cs=contexts(), all=videos(), current=cs.find(c=>c.id===active); if(active!=='all'&&!current){active='all';return render()}
 $('context-nav').innerHTML=cs.map(c=>`<button class="context-nav ${active===c.id?'selected':''}" data-context="${esc(c.id)}"><span></span>${esc(c.name)}</button>`).join('');
 document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('selected',n.dataset.view===view&&active==='all'));
 $('save-count').textContent=state.saved.filter(id=>all.some(v=>v.id===id)).length||'';
 $('focus-kicker').textContent=current?'CURRENT FOCUS':'YOUR CONTEXT'; $('focus-title').textContent=current?current.name:'A feed that follows your work.'; $('focus-task').textContent=current?current.task:'Choose a project to focus your feed, or explore everything below.';
 $('feed-title').textContent=view==='saved'?'Your watch later list':current?`For ${current.name}`:'Picked for what you’re working on';
 $('feed-subtitle').textContent=view==='saved'?'Videos you saved in this browser.':(window.SEED.contextSource==='Empty starter feed'?'No feed updates yet.':`Curated from recent work · ${window.SEED.updatedAt ? 'Updated '+new Date(window.SEED.updatedAt).toLocaleString() : 'Update time unavailable'}`);
 $('filters').innerHTML=[{id:'all',name:'All'},...cs].map(c=>`<button class="chip ${active===c.id&&view==='all'?'active':''}" data-context="${esc(c.id)}">${esc(c.name)}</button>`).join('') + `<button class="chip ${view==='saved'?'active':''}" data-view="saved">♡ Watch later</button><button class="chip" data-new-context>+ Project</button>`;
 const q=$('search').value.trim().toLowerCase();const found=all.filter(v=>(active==='all'||v.context===active)&&(view!=='saved'||state.saved.includes(v.id))&&[v.title,v.channel,v.reason].some(s=>String(s||'').toLowerCase().includes(q)));
 $('grid').innerHTML=found.length?found.map(v=>{const c=cs.find(c=>c.id===v.context);const saved=state.saved.includes(v.id);return `<article class="card"><button class="thumb" data-play="${esc(v.id)}" aria-label="Play ${esc(v.title)}"><img loading="lazy" referrerpolicy="no-referrer" src="https://i.ytimg.com/vi/${esc(v.id)}/hqdefault.jpg" alt=""><span class="play" aria-hidden="true">▶</span></button><div class="card-top"><button class="card-title" data-play="${esc(v.id)}">${esc(v.title)}</button><button class="save ${saved?'is-saved':''}" data-save="${esc(v.id)}" aria-label="${saved?'Remove from':'Add to'} watch later" aria-pressed="${saved}">${saved?'♥':'♡'}</button></div><div class="meta">${esc(v.channel)} · ${esc(c?.name)}</div><div class="reason"><strong>WHY IT'S HERE</strong>${esc(v.reason||'Added to this project by you.')}</div><div class="card-tools"><span>${esc(v.source)}</span><button data-hide="${esc(v.id)}">Remove from feed</button></div></article>`}).join(''):(!q&&view!=='saved'&&!cs.length?`<div class="empty"><h3>Start with a project.</h3><p>Add a project and a video manually, or explore a sample feed. Live chat reading starts paused; review How this works before enabling it.</p><a class="text-button" href="/demo.html">Try a sample feed ↗</a></div>`:`<div class="empty"><h3>Nothing here yet.</h3><p>${q?'Try a different search.':view==='saved'?'Save a video to come back to it later.':'Add a video or ask Codex to update this collection.'}</p></div>`);
}
async function refreshFeed(announce=false){const request=++feedRequest;try{const next=await loadFeed();if(request!==feedRequest)return;const version=JSON.stringify(next);if(version!==feedVersion){window.SEED=next;feedVersion=version;render();if(announce)toast('YourTube updated for your latest work.')}}catch(err){if(request===feedRequest)throw err}}
$('context-nav').addEventListener('click',e=>{const btn=e.target.closest('[data-context]');if(btn)selectContext(btn.dataset.context)});
$('filters').addEventListener('click',e=>{const btn=e.target.closest('[data-context]');if(btn)selectContext(btn.dataset.context);else if(e.target.closest('[data-view]')){active='all';view='saved';render()}else if(e.target.closest('[data-new-context]'))openContext(true)});
$('search').addEventListener('input',render);
document.querySelectorAll('.nav').forEach(button=>button.addEventListener('click',()=>{view=button.dataset.view;active='all';render()}));
$('grid').addEventListener('click',e=>{
 const play=e.target.closest('[data-play]'),save=e.target.closest('[data-save]'),hide=e.target.closest('[data-hide]');
 if(play){const video=videos().find(v=>v.id===play.dataset.play);if(!video)return;$('player-title').textContent=video.title;$('open-youtube').href=`https://www.youtube.com/watch?v=${video.id}`;const frame=document.createElement('iframe');frame.title=video.title;frame.src=`https://www.youtube-nocookie.com/embed/${video.id}?rel=0`;frame.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';frame.referrerPolicy='strict-origin-when-cross-origin';frame.allowFullscreen=true;$('player').replaceChildren(frame);$('player-dialog').showModal()}
 if(save){const id=save.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render()}
 if(hide&&confirm('Remove this video from your feed?')){state.hiddenVideos.push(hide.dataset.hide);state.saved=state.saved.filter(x=>x!==hide.dataset.hide);persist();render();toast('Video removed from your feed.')}
});
$('player-dialog').addEventListener('close',()=>$('player').replaceChildren());
document.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',()=>$(button.dataset.close).close()));
function openContext(isNew=false){const cs=contexts();const context=!isNew?(cs.find(c=>c.id===active)||cs[0]):null;$('context-dialog-title').textContent=context?'Edit your context':'Add a project';$('context-id').value=context?.id||'';$('context-name').value=context?.name||'';$('context-task').value=context?.task||'';$('context-note').value=context?.note||'';$('delete-context').hidden=!context;$('context-dialog').showModal()}
$('add-context').addEventListener('click',()=>openContext(true));$('edit-context').addEventListener('click',()=>openContext(false));$('focus-edit').addEventListener('click',()=>openContext(false));$('how-it-works').addEventListener('click',()=>{$('context-source').textContent='Context used for this collection: '+(window.SEED.contextSource||'Not specified')+'.';$('live-detail').textContent=liveState.message+(liveState.lastSearch?' Last general search: '+liveState.lastSearch:'');$('info-dialog').showModal()});
$('context-form').addEventListener('submit',e=>{e.preventDefault();const id=$('context-id').value||crypto.randomUUID();const item={id,name:$('context-name').value.trim(),task:$('context-task').value.trim(),note:$('context-note').value.trim()};if(!item.name||!item.task)return;if(window.SEED.contexts.some(c=>c.id===id))state.contextEdits[id]=item;else{state.customContexts=state.customContexts.filter(c=>c.id!==id);state.customContexts.push(item)}persist();$('context-dialog').close();active=id;view='all';render();toast('Context saved in this browser.')});
$('delete-context').addEventListener('click',async()=>{const id=$('context-id').value;if(!id||!confirm('Delete this project, its saved context and its videos from YourTube?'))return;try{const response=await fetch('/api/context/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});if(!response.ok)throw Error();state.deletedContexts.push(id);state.customContexts=state.customContexts.filter(c=>c.id!==id);delete state.contextEdits[id];state.customVideos=state.customVideos.filter(v=>v.context!==id);persist();$('context-dialog').close();await refreshFeed();active='all';render();toast('Project and its saved context deleted.')}catch{toast('Could not delete the project. Restart YourTube and try again.')}});
$('add-video').addEventListener('click',()=>{const cs=contexts();if(!cs.length){toast('Add a project first.');return}$('video-form').reset();$('video-error').textContent='';$('video-context').innerHTML=cs.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');if(active!=='all')$('video-context').value=active;$('video-dialog').showModal()});
function parseVideoId(value){try{const u=new URL(value);let id='';if(u.hostname==='youtu.be')id=u.pathname.split('/')[1];else if(['youtube.com','www.youtube.com','m.youtube.com'].includes(u.hostname))id=u.pathname==='/watch'?u.searchParams.get('v'):(u.pathname.match(/^\/(?:shorts|embed)\/([^/]+)/)||[])[1];return /^[a-zA-Z0-9_-]{11}$/.test(id||'')?id:null}catch{return null}}
$('video-form').addEventListener('submit',e=>{e.preventDefault();const id=parseVideoId($('video-url').value.trim());if(!id){$('video-error').textContent='Enter a valid YouTube video link.';return}if(videos().some(v=>v.id===id)){$('video-error').textContent='This video is already in your feed.';return}const item={id,title:$('video-title').value.trim(),channel:$('video-channel').value.trim()||'YouTube',context:$('video-context').value,reason:$('video-reason').value.trim(),source:'Added by you'};if(!item.title)return;state.hiddenVideos=state.hiddenVideos.filter(x=>x!==id);state.customVideos.push(item);persist();$('video-dialog').close();active=item.context;view='all';render();toast('Video added to your feed.')});
render();

 let statusReady=false,liveRequestPending=false,events,reviewRequestId=null;
 const reviewsInFlight=new Set();
 function connectEvents(){
  if(events)events.close();feedRequest++;statusReady=false;$('live-toggle').disabled=true;
  const current=events=new EventSource('/events');
  current.addEventListener('status',e=>{if(events!==current)return;try{const next=JSON.parse(e.data);if(typeof next.enabled!=='boolean'||typeof next.mode!=='string')throw Error('Invalid status');liveState=next;statusReady=true;$('live-toggle').disabled=liveRequestPending;$('live-label').textContent=liveState.mode==='paused'?'Paused':liveState.mode==='error'&&!liveState.watcherReady?'Retry':liveState.mode==='error'?'Live issue':liveState.mode==='awaiting-review'?'Review search':liveState.mode==='curating'||liveState.mode==='searching'||liveState.mode==='waiting'?'Updating…':'Live';$('live-toggle').title=liveState.message;$('live-toggle').classList.toggle('paused',liveState.mode==='paused'||liveState.mode==='error');if($('info-dialog').open)$('live-detail').textContent=liveState.message+(liveState.lastSearch?' Last general search: '+liveState.lastSearch:'');if(liveState.mode==='awaiting-review'&&liveState.requestId){if(reviewRequestId!==liveState.requestId){const replacing=$('search-review').open;reviewRequestId=liveState.requestId;$('search-review-query').value=liveState.pendingQuery||'';$('search-review-error').textContent=replacing?'A new search is ready. Review its phrase before continuing.':''}if(!$('search-review').open)$('search-review').showModal()}else{reviewRequestId=null;if($('search-review').open)$('search-review').close()}}catch{statusReady=false;$('live-toggle').disabled=true}});
  const syncFeed=()=>{if(events!==current)return;refreshFeed(true).catch(()=>{if(events===current)toast('Could not load the updated feed.')})};
  current.addEventListener('open',syncFeed);
  current.addEventListener('feed',syncFeed);
  current.onerror=()=>{if(events!==current)return;feedRequest++;statusReady=false;liveState={mode:'disconnected',message:'Live service disconnected. Restart YourTube.'};$('live-label').textContent='Offline';$('live-toggle').disabled=true;$('live-toggle').classList.add('paused')};
 }
 connectEvents();
 $('live-toggle').addEventListener('click',async()=>{if(!statusReady||liveRequestPending||typeof liveState.enabled!=='boolean')return;const expectedEnabled=liveState.enabled,enabled=!expectedEnabled;statusReady=false;liveRequestPending=true;$('live-toggle').disabled=true;const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);try{const response=await fetch('/api/live',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled,expectedEnabled}),signal:controller.signal});if(!response.ok)throw Error();}catch{toast('Could not change Live. Reconnecting to check its status.')}finally{clearTimeout(timeout);liveRequestPending=false;connectEvents()}});
 async function reviewSearch(action){const requestId=reviewRequestId;if(!requestId||liveState.mode!=='awaiting-review'||liveState.requestId!==requestId||reviewsInFlight.has(requestId))return;const query=$('search-review-query').value;reviewsInFlight.add(requestId);try{const response=await fetch('/api/search-review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({requestId,action,query})});if(!response.ok)throw Error();}catch{if(reviewRequestId===requestId&&$('search-review').open)$('search-review-error').textContent='Could not process that request. Use a general phrase without links, email addresses, or credentials.'}finally{reviewsInFlight.delete(requestId)}}
 $('search-review-form').addEventListener('submit',e=>{e.preventDefault();reviewSearch('approve')});
 $('search-review-cancel').addEventListener('click',()=>reviewSearch('cancel'));
 $('search-review').addEventListener('cancel',e=>{e.preventDefault();reviewSearch('cancel')});
}
start().catch(()=>{document.getElementById('grid').textContent='Unable to load the local feed. Make sure YourTube is running through its local server.'});
